const CSS = `:root{--bg:#ECE9E3;--ink:#1C1E22;--soft:#3A3D43;--muted:#5B554D;--pri:#1C1E22;--brass:#F3C978;--card:#FFFFFF;--line:#E2DCD1;--link:#87591C}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 -apple-system,Segoe UI,Roboto,Inter,sans-serif}
header{background:var(--pri);color:#F5F3EE;padding:28px 16px 22px}header .w,main{max-width:760px;margin:0 auto}
.brand{font:700 22px Georgia,serif;color:var(--brass)}.slogan{color:#D9D4CA;font-size:14px}
h1{font:700 28px Georgia,serif;margin:14px 0 0}nav{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
nav button{border:1px solid rgba(243,201,120,.55);background:transparent;color:var(--brass);border-radius:99px;padding:8px 12px;min-height:44px;font-size:14px;cursor:pointer}
nav button.on{background:var(--brass);color:#1A1206}main{padding:20px 16px 60px}section{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin:12px 0}
h2{font:700 18px Georgia,serif;margin:0 0 6px;color:var(--ink)}p{margin:0;color:var(--soft)}.upd{color:var(--muted);font-size:13px;margin-top:18px}
a{color:var(--link);overflow-wrap:anywhere}p{overflow-wrap:anywhere}.mail{font-weight:600}`;

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Bölüm metni bilinçli HTML içerir (bağlantılar); başlıklar kaçışlanır.
function sayfa(ad) {
  const s = SAYFALAR[ad];
  const bas = DILLER.map((d) => `<div data-l="${d}" hidden><h1>${esc(s.baslik[d])}</h1><div class="slogan">Pipe Rotation System</div></div>`).join('');
  const nav = DILLER.map((d) => `<button data-k="${d}" onclick="show('${d}')">${AD[d]}</button>`).join('');
  const govde = DILLER.map((d) => `<div data-l="${d}" hidden>${s.bolum[d].map(([h, p]) => `<section><h2>${esc(h)}</h2><p>${p}</p></section>`).join('')}<p class="upd">${SON[d]}: ${GUNCEL[d]}</p></div>`).join('');
  const js = `const L=${JSON.stringify(DILLER)};function show(l){document.querySelectorAll('[data-l]').forEach(e=>e.hidden=e.dataset.l!==l);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('on',b.dataset.k===l));document.documentElement.lang=l;document.title=document.querySelector('[data-l="'+l+'"] h1').textContent+' · PRS';try{localStorage.setItem('pipotr-l',l)}catch(e){}}
function pick(){const q=new URLSearchParams(location.search).get('l');if(L.includes(q))return q;try{const s=localStorage.getItem('pipotr-l');if(L.includes(s))return s}catch(e){}
for(const n of (navigator.languages||[navigator.language])){const lc=(n||'').toLowerCase();if(lc.endsWith('-tr'))return 'tr';const c=lc.split('-')[0];if(L.includes(c))return c}return 'en'}show(pick());`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PRS</title><style>${CSS}</style></head><body><header><div class="w"><div class="brand">PRS</div>${bas}<nav>${nav}</nav></div></header><main>${govde}</main><script>${js}</script></body></html>\n`;
}

// Denetim: 8 dil tam, bölüm sayıları eşit, yasak sözler yok
const YASAK = /tütün|tutun|tobacco|tabak|tabac|tabaco|tobak|smoking|ücretsiz|destekçi/i;
let hata = 0;
for (const [ad, s] of Object.entries(SAYFALAR)) {
  const n = s.bolum.tr.length;
  for (const d of DILLER) {
    if (!s.baslik[d] || !s.bolum[d]) { console.error(`${ad}: ${d} eksik`); hata++; continue; }
    if (s.bolum[d].length !== n) { console.error(`${ad}: ${d} bölüm sayısı ${s.bolum[d].length} ≠ ${n}`); hata++; }
    for (const [h, p] of s.bolum[d]) if (YASAK.test(h + p)) { console.error(`${ad}/${d}: yasak söz: ${h}`); hata++; }
  }
}
if (hata) process.exit(1);

const denetle = process.argv.includes('--denetle');
mkdirSync(new URL('../prs/', import.meta.url), { recursive: true });
for (const ad of Object.keys(SAYFALAR)) {
  const yol = new URL(`../prs/${ad}.html`, import.meta.url);
  const yeni = sayfa(ad);
  if (denetle) {
    let eski = '';
    try { eski = readFileSync(yol, 'utf8'); } catch {}
    if (eski.replaceAll('\r\n', '\n') !== yeni) { console.error(`prs/${ad}.html güncel değil`); process.exit(1); }
  } else writeFileSync(yol, yeni);
}
console.log(denetle ? 'prs/*.html güncel' : 'prs/gizlilik.html, prs/kosullar.html, prs/destek.html yazıldı');
